<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\Accessor\UserConsentPurposesConsentPurposeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentPurposesConsentPurposeAccessor trait.
 *
 * Covers null default, string/VO assignment via withConsentPurpose,
 * getConsentPurpose/consentPurpose accessors, and isConsentPurposeChanged with/without original.
 */
class UserConsentPurposesConsentPurposeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withConsentPurpose creates a new instance with the ConsentPurpose set
     * from a string value, and getConsentPurpose returns the primitive string.
     */
    public function testWithConsentPurposeFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesConsentPurposeAccessorUnitTest();

        // Act
        $result = $holder->withConsentPurpose(new ConsentPurposeRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new ConsentPurposeRef('one'), $result->getConsentPurpose());
    }
    /**
     * Asserts that withconsentPurpose has access to the value object
     * from a string value, and getConsentPurpose returns the primitive string.
     */
    public function testWithConsentPurposeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesConsentPurposeAccessorUnitTest();

        // Act
        $result = $holder->withConsentPurpose(new ConsentPurposeRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new ConsentPurposeRef('one'), $result->consentPurpose()->value());
    }
    public function testChangedConsentPurpose(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesConsentPurposeAccessorUnitTest()->withConsentPurpose(new ConsentPurposeRef('one'));
        $original = $holder->withConsentPurpose(new ConsentPurposeRef('one'));
        $same = $holder->withConsentPurpose(new ConsentPurposeRef('one'));
        $modified = $holder->withConsentPurpose(new ConsentPurposeRef('other'));

        // Act
        $withSame = $original->isConsentPurposeChanged($same);
        $withDiferent = $original->isConsentPurposeChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserConsentPurposesConsentPurposeAccessorUnitTest
{
    use UserConsentPurposesConsentPurposeAccessor;
}
